// Hand-curated Phase 3 domain deep-dive views.
//
// Each view is authored independently — its own canvas, groups, node positions and
// explicit edge waypoints — never generated by filtering src/data/curatedView.ts's Total
// Architecture. Node/edge ids are namespaced per view (e.g. `sc-` for store-checkout) so
// views never collide when the router mounts more than one at a time in tests.
//
// Sourced from fullResearchCatalogue: components, architecture_edges and research_gaps in
// src/data/action-architecture-data.json (see docs/PHASE3_REVIEW_REPORT.md for the id
// mapping this was checked against). `canonicalRelationshipIds` cites the real EDGE-00xx
// record each curated edge visualises.
import type { ArchitectureView } from '@/types/architecture';

const RULES = {
  autoLayout: false as const,
  draggableNodes: false as const,
  showMinimap: false as const,
  renderAllCatalogRecords: false as const,
  edgeRouting: 'explicit-waypoints-only' as const,
  edgesBehindNodes: true as const,
  maxVisibleTopLevelCards: 16,
  maxVisibleGaps: 8,
  hideEdgeLabelsUntilHover: true,
};

